In #66 and #68, `array_tree` was added with very helpful functionality.  This might be defeating the whole purpose, but it seems we might want to preserve names, especially since the alternative `alply` behaves differently.  This code is ugly but accomplishes the job.  If nothing else, maybe someone would like to see some additional uses of `purrr`.

```
library(purrr)

depth_exists <- function(l,depth){
  inherits(try(at_depth(l,depth,~NULL),silent=TRUE),"list")
}

set_names_recursive <- function(l,arr,nms,selector){

  all_names <- nms
  nms <- nms[selector]

  depth <- 1
  l <- set_names(l,nms[[depth]])

  recurse <- function(l){
    # find depth
    iter <- 1
    while(depth_exists(l,iter)){
      iter <- iter + 1
    }
    depth <<- length(nms) + 3 - iter

    l <- set_names(l, nms[[depth]])

    if( depth < length(nms) ){
      l <- map(
        l,
        ~{recurse(.x)}
      )
    } else {
      try(
        {l<-map(
          l,
          ~array(.x,dim=dim(arr)[-selector],dimnames=all_names[-selector])
        )},
        silent = TRUE
      )
    }

    l
  }

  recurse(l)
}

array_tree_named <- function(arr, margin = NULL){
  if(!is.array(arr)){
    stop("please provide an array as the argument",call.= FALSE)
  }

  selector = margin
  # selector needs to be non-NULL for `[`
  #   so set selector to all if margin is NULL
  if(is.null(margin)) selector = 1:length(dimnames(arr))

  set_names_recursive(
    array_tree(arr,margin),
    arr,
    dimnames(arr),
    selector
  )
}
```

As an illustration of its use, we can do this.

```
array_tree_named(Titanic)

array_tree_named(Titanic,c(1,3))
```

